 "content": "def transform(grid):
    """Restore 6s using the grid's transpose and central horizontal/vertical symmetries."""
    n, m = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    def orbit(r, c):
        seen = {(r, c)}
        todo = [(r, c)]
        while todo:
            a, b = todo.pop()
            # Symmetries in these grids: main-diagonal reflection and
            # horizontal/vertical reflections about the central axes.
            candidates = ((b, a), (31-a, b), (a, 31-b))
            for x, y in candidates:
                if 0 <= x < n and 0 <= y < m and (x, y) not in seen:
                    seen.add((x, y))
                    todo.append((x, y))
        return seen
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 6:
                cells = orbit(r, c)
                known = [grid[a][b] for a, b in cells if grid[a][b] != 6]
                if known:
                    # Exact symmetries make all known orbit values agree.
                    out[r][c] = known[0]
    return out
